def _resolve_memory_fs_mode(use_memory_fs: bool | None, root: str) -> tuple[bool, str]:
    available = is_memory_fs_available(root)
    if use_memory_fs is True and not available:
        raise MemoryFileSystemUnavailableError(
            f"Memory file system is unavailable at {root!r}."
        )

    enabled = available if use_memory_fs is None else bool(use_memory_fs)
    return enabled, "memory_fs" if enabled else "pipe"


