    return asdict(_CONFIG)


def _dump_to_file(payload: Any, root: str, prefix: str) -> str:
    file_descriptor, path = tempfile.mkstemp(prefix=prefix, suffix=".dill", dir=root)
    os.close(file_descriptor)
    with open(path, "wb") as handle:
        dill.dump(payload, handle)
    return path


def _load_from_file(path: str) -> Any:
    try:
        with open(path, "rb") as handle:
            return dill.load(handle)
    finally:
        try:
            os.remove(path)
        except OSError:
            pass


