    return dill.loads(payload_ref)


def _make_error_payload(exception: BaseException) -> dict[str, Any]:
    payload: dict[str, Any] = {
        "exception_bytes": None,
        "exception_type": type(exception).__name__,
        "exception_repr": repr(exception),
        "traceback": traceback.format_exc(),
    }
    try:
        payload["exception_bytes"] = dill.dumps(exception)
    except Exception:
        payload["exception_bytes"] = None
    return payload


