from typing import Any

from pandas import option_context
from pandas.core.groupby.generic import DataFrameGroupBy, SeriesGroupBy
from pandas.core.groupby.ops import _is_indexed_like

from .generic import patch_method


def _groupby_apply_chunk(payload: dict[str, Any]) -> dict[str, Any]:
    results = []
    mutated = False
    axis = payload["axis"]
    func = payload["func"]
    args = payload["args"]
    kwargs = payload["kwargs"]

    for key, group in payload["groups"]:
        object.__setattr__(group, "name", key)
        group_axes = group.axes
        result = func(group, *args, **kwargs)
        if not mutated and not _is_indexed_like(result, group_axes, axis):
            mutated = True
        results.append(result)

    return {"results": results, "mutated": mutated}


def _parallel_groupby_apply(groupby_obj, data, func, args, kwargs):
    from pandarallel.core import get_runtime_config, run_parallel_tasks
    from pandarallel.utils import chunk_sequence

    groups = list(groupby_obj._grouper.get_iterator(data, axis=groupby_obj.axis))
    if len(groups) <= 1:
        return groupby_obj._python_apply_general(
            lambda group: func(group, *args, **kwargs),
            data,
        )

    payloads = [
        {
            "groups": batch,
            "func": func,
            "args": args,
            "kwargs": kwargs,
            "axis": groupby_obj.axis,
        }
        for batch in chunk_sequence(groups, get_runtime_config().nb_workers)
    ]

    batch_results = run_parallel_tasks(
        _groupby_apply_chunk,
        payloads,
        description=f"{type(groupby_obj).__name__}.apply",
    )

    values = []
    mutated = False
    for batch_result in batch_results:
        mutated = mutated or batch_result["mutated"]
        values.extend(batch_result["results"])

    return groupby_obj._wrap_applied_output(data, values, mutated, False)


def dataframe_groupby_parallel_apply(self, func, *args, include_groups: bool = True, **kwargs):
    if isinstance(func, str) or not callable(func):
        return self.apply(func, *args, include_groups=include_groups, **kwargs)

    if not include_groups:
        return _parallel_groupby_apply(self, self._obj_with_exclusions, func, args, kwargs)

    with option_context("mode.chained_assignment", None):
        try:
            return _parallel_groupby_apply(self, self._selected_obj, func, args, kwargs)
        except TypeError:
            return _parallel_groupby_apply(
                self,
                self._obj_with_exclusions,
                func,
                args,
                kwargs,
            )


def series_groupby_parallel_apply(self, func, *args, **kwargs):
    if isinstance(func, str) or not callable(func):
        return self.apply(func, *args, **kwargs)

    return _parallel_groupby_apply(self, self._selected_obj, func, args, kwargs)


