    patch_method(SeriesGroupBy, "parallel_apply", series_groupby_parallel_apply)

from __future__ import annotations

import math
import os
import sys
import threading
from dataclasses import dataclass


def _in_notebook() -> bool:
    try:
        from IPython import get_ipython
    except Exception:
        return False

    shell = get_ipython()
    if shell is None:
        return False

    return shell.__class__.__name__ == "ZMQInteractiveShell"


@dataclass
class BaseProgressBar:
    total: int
    enabled: bool = True
    description: str = "Processing"

    def __post_init__(self) -> None:
        self.total = max(int(self.total), 0)
        self._current = 0
        self._closed = False
        self._lock = threading.Lock()

    def __enter__(self) -> "BaseProgressBar":
        if self.enabled:
            self.render()
        return self

    def __exit__(self, exc_type, exc, tb) -> None:
        self.close()

    def update(self, step: int = 1) -> None:
        if not self.enabled or self._closed:
            return

        with self._lock:
            self._current = min(self.total, self._current + step)
            self.render()

    def render(self) -> None:
        raise NotImplementedError

    def close(self) -> None:
        if not self.enabled or self._closed:
            return
        self._closed = True
        sys.stderr.write("\n")
        sys.stderr.flush()


class NullProgressBar(BaseProgressBar):
    def render(self) -> None:
        return None

    def close(self) -> None:
        self._closed = True


class TerminalProgressBar(BaseProgressBar):
    def render(self) -> None:
        total = max(self.total, 1)
        ratio = self._current / total
        width = 28
        filled = int(math.floor(width * ratio))
        bar = "#" * filled + "." * (width - filled)
        percent = int(ratio * 100)
        line = (
            f"\r{self.description}: [{bar}] "
            f"{self._current}/{self.total} {percent:3d}%"
        )
        sys.stderr.write(line)
        sys.stderr.flush()


class NotebookProgressBar(TerminalProgressBar):
    pass


def create_progress_bar(
    total: int,
    enabled: bool = False,
    description: str = "Processing",
) -> BaseProgressBar:
    if not enabled or total <= 0:
        return NullProgressBar(total=total, enabled=False, description=description)

    if _in_notebook() or os.environ.get("JPY_PARENT_PID"):
        return NotebookProgressBar(total=total, enabled=True, description=description)

    return TerminalProgressBar(total=total, enabled=True, description=description)

